export function regionOf(key) {
  const r = REGIONS[key];
  if (!r) return null;
  const p = PAGES[r.page];
  return { key, ...r, sourceImage: p.src, pdf: p.pdf, printed: p.printed, w: p.w, h: p.h, view: p.view };
}

export function assetOf(lessonId) {
  const a = ASSET_MAP[lessonId];
  if (!a) return null;
  const fig = regionOf(a.fig);
  if (!fig) return null;
  return { ...fig, purpose: a.purpose, reveal: a.reveal ? regionOf(a.reveal) : null, textOnlyUntilLock: !!a.textOnlyUntilLock };
}

export function pageSrc(pdf) {
  return PAGES[Number(pdf)]?.src || null;
}

const esc = (t) => String(t ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

function cropSpan(r, alt) {
  const c = r.crop;
  const ar = (c.w * r.w) / (c.h * r.h);
  return `<span class="pkfbCrop pkfcbCrop" style="--cx:${c.x};--cy:${c.y};--cw:${c.w};--ch:${c.h};--ar:${ar.toFixed(4)}"><img src="${esc(r.sourceImage)}" alt="${esc(alt)}" width="${r.w}" height="${r.h}" decoding="async" draggable="false"/></span>`;
}

function enlargeAttrs(r, c) {
  return `data-src="${esc(r.sourceImage)}" data-w="${r.w}" data-h="${r.h}" data-cx="${c.x}" data-cy="${c.y}" data-cw="${c.w}" data-ch="${c.h}"`;
}

/** Original-JPEG region as a CSS viewport (aspect ratio from the crop; height-based positioning). */
export function regionHTML(r, { alt = 'PKF example', fullBtn = true, label = '' } = {}) {
  if (!r) return '<p class="muted">No source image for this lesson.</p>';
  const v = r.view;
  const btn = fullBtn
    ? `<button type="button" class="chip pkfbFullBtn" data-action="pkfcb-enlarge" ${enlargeAttrs(r, v)}>VIEW FULL PKF EXAMPLE</button>`
    : '';
  const pageLabel = r.printed != null ? r.printed : r.page;
  return `<div class="pkfbFig pkfcbFig" data-pkfcb-fig="${esc(r.key)}" data-page="${r.page}">
    ${label ? `<p class="pkfbFigLabel">${esc(label)}</p>` : ''}
    <button type="button" class="pkfbCropBtn" data-action="pkfcb-enlarge" ${enlargeAttrs(r, r.crop)} aria-label="Enlarge PKF example">${cropSpan(r, alt)}</button>
    <p class="pkfbCite muted small">PKF page ${pageLabel} · ${esc(r.figs)} · tap to enlarge</p>
    ${btn}
  </div>`;
}

export function figureHTML(lessonId, opts = {}) {
  const a = assetOf(lessonId);
  if (!a) return '<p class="muted">No source image for this lesson.</p>';
  if (a.textOnlyUntilLock && opts.hideUntilLock) {
    return `<div class="card pkfcbHiddenFig" data-pkfcb-hidden-fig="1"><p class="muted small">Figure hidden until you LOCK ANSWER (the printed answer is on the page).</p></div>`;
  }
  return regionHTML(a, opts);
}

export function revealFigureHTML(lessonId, opts = {}) {
  const a = assetOf(lessonId);
  if (!a?.reveal) return a && !a.textOnlyUntilLock ? '' : (a ? regionHTML(a, { label: 'PKF SOLUTION · ORIGINAL PAGE', ...opts }) : '');
  return regionHTML(a.reveal, { label: 'PKF SOLUTION · ORIGINAL PAGE', ...opts });
}
